import{_ as n,p as a,q as s,Y as e}from"./framework-e1bed10d.js";const t={},i=e(`<h1 id="注解" tabindex="-1"><a class="header-anchor" href="#注解" aria-hidden="true">#</a> 注解</h1><h2 id="注解的作用" tabindex="-1"><a class="header-anchor" href="#注解的作用" aria-hidden="true">#</a> 注解的作用</h2><p>说明：对代码进行说明，生成api文档</p><p>检查：检查代码是否符合条件，如@Override检查方式是否为重写方法，@FunctionalInterface检查是否为函数式接口</p><p>分析：对代码进行分析，起到代替配置文件的作用</p><h2 id="注解的生命周期" tabindex="-1"><a class="header-anchor" href="#注解的生命周期" aria-hidden="true">#</a> 注解的生命周期</h2><ol><li>SOURCE：@Retention(RetentionPolicy.SOURCE)，在源文件中有效，被编译器丢弃</li><li>CLASS：@Retention(RetentionPolicy.CLASS)，在class文件中有效，被JVM加载，但JVM退出时丢弃</li><li>RUNTIME：@Retention(RetentionPolicy.RUNTIME)，在JVM加载时有效，可以通过反射获取注解信息，并根据注解的定义执行相应的代码</li></ol><h2 id="注解的作用目标" tabindex="-1"><a class="header-anchor" href="#注解的作用目标" aria-hidden="true">#</a> 注解的作用目标</h2><p>注解的目标定义了注解将适用于哪一种级别的 Java 代码上，有些注解只适用于方法，有些只适用于成员变量，有些只适用于类，有些则都适用。截止到 Java 9，注解的类型一共有 11 种，定义在 ElementType 枚举中。</p><ul><li>TYPE：用于类、接口、注解、枚举</li><li>FIELD：用于字段（类的成员变量），或者枚举常量</li><li>METHOD：用于方法</li><li>PARAMETER：用于普通方法或者构造方法的参数</li><li>CONSTRUCTOR：用于构造方法</li><li>LOCAL_VARIABLE：用于变量</li><li>ANNOTATION_TYPE：用于注解</li><li>PACKAGE：用于包</li><li>TYPE_PARAMETER：用于泛型参数</li><li>TYPE_USE：用于声明语句、泛型或者强制转换语句中的类型</li><li>MODULE：用于模块</li></ul><h2 id="注解的定义" tabindex="-1"><a class="header-anchor" href="#注解的定义" aria-hidden="true">#</a> 注解的定义</h2><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Retention</span><span class="token punctuation">(</span><span class="token class-name">RetentionPolicy</span><span class="token punctuation">.</span><span class="token constant">RUNTIME</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@Target</span><span class="token punctuation">(</span><span class="token class-name">ElementType</span><span class="token punctuation">.</span><span class="token constant">FIELD</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token annotation punctuation">@interface</span> 注解名称 <span class="token punctuation">{</span>
    数据类型 属性名<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    数据类型 属性名<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">default</span> 默认值<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>数据类型可以是8中基本类型、String、Class、enum、注解以及以上的一维数组组合</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Retention</span><span class="token punctuation">(</span><span class="token class-name">RetentionPolicy</span><span class="token punctuation">.</span><span class="token constant">RUNTIME</span><span class="token punctuation">)</span>
<span class="token annotation punctuation">@Target</span><span class="token punctuation">(</span><span class="token class-name">ElementType</span><span class="token punctuation">.</span><span class="token constant">FIELD</span><span class="token punctuation">)</span>
<span class="token keyword">public</span> <span class="token annotation punctuation">@interface</span> <span class="token class-name">Book</span><span class="token punctuation">{</span>
    <span class="token class-name">String</span> <span class="token function">name</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">double</span> <span class="token function">price</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">default</span> <span class="token number">12.34</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="注解的使用" tabindex="-1"><a class="header-anchor" href="#注解的使用" aria-hidden="true">#</a> 注解的使用</h2><p>注解的使用本质上是给注解的属性赋值，注解可以在类、方法、属性、参数、局部变量上使用</p><p>使用格式：</p><ul><li>@注解名(属性名=值,属性名=值)</li><li>@注解名(属性名={a,b,c},属性名=属性值)</li><li>@注解名(value=值)，这种情况可以省略value使用<code>@注解名(值)</code>的形式</li></ul><h2 id="注解的解析" tabindex="-1"><a class="header-anchor" href="#注解的解析" aria-hidden="true">#</a> 注解的解析</h2><p>注解的解析，本质上是将注解中的属性值获取出来</p>`,20),l=[i];function p(c,o){return a(),s("div",null,l)}const d=n(t,[["render",p],["__file","annotation.html.vue"]]);export{d as default};
